const themes = {
  orbita: {number:'02',name:'Órbita',label:'Ideas en movimiento',tag:'Aero nocturno',description:'Un pequeño estudio de animación. Índigo profundo, reflejos contenidos y un lienzo oscuro donde el código y las formas toman el protagonismo.',aero:55,bg:'#191E29',accent:'#B5AFF2',surface:'#262D40',text:'#EAE8E3',radius:'12 px',font:'Segoe UI · sans serif',shadow:'Glow difuso y neón localizado en los bordes',note:'El contenido respira sobre un lienzo abierto. La navegación usa cristal metálico oscuro y transparente, con números biselados y un brillo de acero que se intensifica hacia la derecha; la pestaña activa añade un acento menta contenido. El Aero se concentra en código y tarjetas: degradados glow continuos y contornos de neón más intensos donde incide la luz, que se desvanecen hacia los tramos oscuros. Las cabeceras usan luz difusa en lugar de bandas de reflejo. Las figuras usan el mismo material: glow interior continuo y bordes de neón graduados en menta, lila y coral, sin cortes de reflejo. El neón menta (#95EBD0) y lila (#BDAAFF) aparece en la sintaxis, una línea fina del editor y los indicadores del laboratorio. La luz se concentra en detalles pequeños para preservar la calma del Aero.'}
};
const theme = document.body.dataset.theme;
const app = document.querySelector('#app');
const icon = (name, size=18) => {
 const paths = {play:'<path d="m9 5 11 7-11 7z"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M15 8V4H4v11h4"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',check:'<path d="m5 12 4 4L19 6"/>',palette:'<circle cx="12" cy="12" r="9"/><circle cx="8" cy="9" r="1"/><circle cx="15" cy="8" r="1"/><circle cx="17" cy="14" r="1"/><path d="M7 16h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',replay:'<path d="M4 5v6h6M4 11a8 8 0 1 1 1 7"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>'};
 return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;
};
const mark = `<span class="brand-mark" aria-hidden="true"><i></i><b></b><em></em></span>`;
const brand = `<a class="brand" href="index.html">${mark}<span>Manim<span class="brand-sub">APRENDER EN MOVIMIENTO</span></span></a>`;
const source = `from manim import *

class PrimeraEscena(Scene):
    def construct(self):
        circulo = Circle(color="#8BAF9B")
        circulo.set_fill("#8BAF9B", opacity=0.25)
        cuadrado = Square(color="#8588BE")
        cuadrado.set_fill("#8588BE", opacity=0.25)

        self.play(Create(circulo))
        self.wait(0.5)
        self.play(Transform(circulo, cuadrado), run_time=2)
        self.wait()
`;
const escapeHtml = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
function highlight(s){return escapeHtml(s).replace(/("[^"\n]*"|\b(?:from|import|class|def)\b|\b(?:Scene|Circle|Square|Create|Transform|PrimeraEscena)\b|\b(?:self)\b|\b\d+(?:\.\d+)?\b)/g,m=>`<span class="${m.startsWith('"')?'str':/^(from|import|class|def)$/.test(m)?'kw':m==='self'?'self':/^\d/.test(m)?'num':'fn'}">${m}</span>`);}
function designToolbar(){return `<div class="design-toolbar"><a href="index.html" class="design-label">Órbita <span>· Guía de estilos</span></a><button class="style-trigger" data-open-guide>${icon('palette',16)}<span>Ficha de estilo</span></button></div>`;}
function sidebar(){return `<aside class="sidebar" id="course-menu"><div class="sidebar-title"><span>EL RECORRIDO</span><span>01 — 04</span></div><nav aria-label="Contenido de la lección"><a href="#introduccion" class="lesson-link active"><span class="lesson-no">01</span><span>Tu primera escena<small>Un círculo, muchas posibilidades</small></span></a><a href="#codigo" class="lesson-link"><span class="lesson-no">02</span><span>Del código al lienzo<small>Construye paso a paso</small></span></a><a href="#conceptos" class="lesson-link"><span class="lesson-no">03</span><span>Las piezas esenciales<small>Scene, Mobject y Animation</small></span></a><a href="#practica" class="lesson-link"><span class="lesson-no">04</span><span>Ahora te toca a ti<small>Un pequeño experimento</small></span></a></nav><div class="course-note"><span class="note-orb">${icon('book',22)}</span><strong>Una idea a la vez.</strong><p>No necesitas saberlo todo para empezar a crear.</p><span class="course-line"></span><small>FUNDAMENTOS DE MANIM</small></div><a class="reference-link" href="https://docs.manim.community/en/stable/tutorials/quickstart.html" target="_blank" rel="noopener">Documentación de Manim CE ↗</a></aside>`;}
function hero(){return `<section class="lesson-hero" id="introduccion"><div class="hero-text"><p class="eyebrow"><span class="chapter-dot"></span> EL COMIENZO DE ALGO &nbsp; / &nbsp; LECCIÓN 01</p><h1>Todo empieza<br>con <em>una forma.</em></h1><p>Convierte unas líneas de Python en una idea que se mueve.<br class="desktop"> Tu primera animación de Manim empieza aquí.</p><div class="hero-actions"><a class="primary-btn" href="#codigo">${icon('play',16)} Crear mi primera escena</a><span class="read-time">8 min de lectura <i>·</i> Nivel inicial</span></div></div><div class="hero-art" aria-hidden="true"><div class="art-grid"></div><span class="hero-circle"></span><span class="hero-square"></span><svg class="hero-triangle" viewBox="0 0 110 100" aria-hidden="true"><defs><radialGradient id="logo-coral-fill" cx="28%" cy="15%" r="105%"><stop offset="0" stop-color="#FFC4A8" stop-opacity=".82"/><stop offset=".35" stop-color="#EE9B7B" stop-opacity=".64"/><stop offset=".75" stop-color="#C76C59" stop-opacity=".40"/><stop offset="1" stop-color="#DF8E71" stop-opacity=".52"/></radialGradient><linearGradient id="logo-coral-edge" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFE1CE" stop-opacity=".95"/><stop offset=".25" stop-color="#FFB294" stop-opacity=".88"/><stop offset=".55" stop-color="#D88770" stop-opacity=".22"/><stop offset=".78" stop-color="#EFA082" stop-opacity=".30"/><stop offset="1" stop-color="#FFD1B8" stop-opacity=".85"/></linearGradient></defs><path d="M55 2 L108 98 L2 98 Z" fill="url(#logo-coral-fill)" stroke="url(#logo-coral-edge)" stroke-width="1.2" stroke-linejoin="round"/></svg></div></section>`;}
function codePanel(){return `<section class="code-panel" aria-labelledby="code-title"><div class="panel-bar"><span id="code-title">${icon('code',16)} primera_escena.py</span><button data-copy="source" class="copy-btn" aria-label="Copiar código Python">${icon('copy',14)} <span>Copiar</span></button></div><pre tabindex="0" aria-label="Código Python de la primera escena"><code>${source.trimEnd().split('\n').map((s,i)=>`<span class="code-line"><span class="line-no" aria-hidden="true">${i+1}</span><span>${highlight(s)||' '}</span></span>`).join('')}</code></pre><div class="code-status"><span><i></i> Python · Manim CE</span><button data-download>${icon('download',13)} Descargar .py</button></div></section>`;}
function previewPanel(){return `<section class="preview-panel" aria-labelledby="preview-title"><div class="panel-bar"><span id="preview-title"><i class="live-dot"></i> Vista previa</span><span class="small-label">DEMO INTERACTIVA</span></div><div class="preview-stage"><div class="stage-grid"></div><div class="stage-axis axis-x"></div><div class="stage-axis axis-y"></div><div class="morph-shape"></div><span class="stage-tag">${icon('code',12)} <span id="stage-operation">Circle → Square</span></span><span class="axis-label">x</span><span class="axis-label y-label">y</span></div><div class="player-controls"><button class="play-button" data-play aria-label="Reproducir animación">${icon('play',17)}</button><input id="timeline" type="range" min="0" max="1000" value="0" aria-label="Posición de la animación"><span id="time-label">0.0 / 4.5 s</span><button class="reset-button" data-reset aria-label="Reiniciar animación">${icon('replay',15)}</button></div><p class="demo-caption">Simulación visual en el navegador · no ejecuta Python</p></section>`;}
function lesson(){const t=themes[theme];app.innerHTML=`<a class="skip-link" href="#main">Saltar al contenido</a>${designToolbar()}<div class="site-shell"><header class="site-header">${brand}<nav class="header-nav" aria-label="Navegación principal"><a href="#introduccion" class="selected">Aprender</a><a href="#codigo">Laboratorio</a><a href="#practica">Practicar</a></nav><span class="header-caption">Matemáticas que se ven.</span><button class="menu-button" aria-expanded="false" aria-controls="course-menu">${icon('menu')}<span>Lección</span></button></header><div class="lesson-layout">${sidebar()}<main id="main" class="lesson-main"><div class="breadcrumbs"><span>Aprender</span><span>›</span><span>Fundamentos</span><span>›</span><strong>Tu primera escena</strong><span class="lesson-edition">MANIM COMMUNITY</span></div>${hero()}<section class="work-section" id="codigo"><div class="section-heading"><div><p class="eyebrow">01 / DEL CÓDIGO AL LIENZO</p><h2>Pequeño código. Primer movimiento.</h2></div><span class="lesson-chip">${icon('code',14)} Python</span></div><p class="section-description">Creamos un círculo y lo transformamos en un cuadrado. Cada línea tiene su papel.</p><div class="lab-grid">${codePanel()}${previewPanel()}</div><div class="terminal"><span class="terminal-label">EN TU TERMINAL</span><code><span>$</span> manim -pql primera_escena.py PrimeraEscena</code><button data-copy="command" aria-label="Copiar comando de terminal">${icon('copy',16)}</button></div><aside class="tip"><span class="tip-icon">i</span><p><strong>Una pausa también cuenta.</strong> <code>self.wait()</code> deja respirar la escena. El tiempo es parte de lo que quieres explicar.</p></aside></section><section id="conceptos" class="concepts"><div class="section-heading"><div><p class="eyebrow">02 / LAS PIEZAS ESENCIALES</p><h2>Tres ideas para empezar.</h2></div></div><div class="concept-grid"><article><span class="concept-symbol scene-symbol">▣</span><span class="concept-number">01</span><h3>La escena</h3><code>Scene</code><p>Es tu escenario. Dentro de <code>construct()</code> decides qué aparece y en qué orden.</p></article><article><span class="concept-symbol object-symbol">○</span><span class="concept-number">02</span><h3>Los objetos</h3><code>Mobject</code><p>Son las piezas visuales: formas, texto o fórmulas. Aquí usamos <code>Circle</code> y <code>Square</code>.</p></article><article><span class="concept-symbol animation-symbol">↗</span><span class="concept-number">03</span><h3>El movimiento</h3><code>Animation</code><p><code>self.play()</code> reproduce la acción. <code>Transform</code> lleva un objeto hacia otra forma.</p></article></div></section><section class="practice" id="practica"><div class="practice-icon">✦</div><div><p class="eyebrow">03 / APRENDER HACIENDO</p><h2>¿Y si el destino fuera un triángulo?</h2><p>Cambia <code>Square</code> por <code>Triangle</code> y prueba un <code>run_time</code> de 3 segundos. Antes de ejecutarlo, imagina el resultado.</p><details><summary>Ver una pista <span>+</span></summary><div class="hint"><p>Puedes conservar el nombre de la variable, aunque renombrarla como <code>triangulo</code> haría más claro el código. Actualiza también su uso en <code>Transform</code>.</p><pre><code>triangulo = Triangle(color="#CD7F66")
triangulo.set_fill("#CD7F66", opacity=0.25)
self.play(Transform(circulo, triangulo), run_time=3)</code></pre></div></details></div><button class="complete-button" data-complete>${icon('check',16)}<span>Marcar como completada</span></button></section><footer class="lesson-footer"><span>${mark} Una forma. Una idea. Un paso más.</span><button data-open-guide>Explorar el estilo ${t.name} ${icon('arrow',15)}</button></footer></main></div></div><dialog class="style-dialog"><div class="dialog-top"><span>FICHA DE ESTILO / ÓRBITA</span><button data-close-guide aria-label="Cerrar ficha">${icon('close',20)}</button></div><div class="dialog-content"><p class="eyebrow">${t.tag}</p><h2>${t.name}<em>${t.label}</em></h2><p>${t.description}</p><h3>La paleta</h3><div class="token-swatches">${[['Fondo',t.bg],['Acento',t.accent],['Superficie',t.surface],['Texto',t.text],['Salvia','#8BBDA3'],['Coral','#DF866B']].map(([label,color])=>`<button data-color="${color}" aria-label="Copiar color ${label} ${color}"><i style="background:${color}"></i><strong>${label}</strong><code>${color}</code></button>`).join('')}</div><h3>Tipografía y material</h3><dl><div><dt>Familias</dt><dd>${t.font}</dd></div><div><dt>Código</dt><dd>SFMono / Consolas · 13 px</dd></div><div><dt>Radios</dt><dd>${t.radius}</dd></div><div><dt>Sombras</dt><dd>${t.shadow}</dd></div><div><dt>Escala tipográfica</dt><dd>48 / 26 / 18 / 15 / 12 px</dd></div></dl><p class="design-note">${t.note}</p><button class="primary-btn" data-tokens>${icon('download',16)} Descargar variables CSS</button></div></dialog><div class="toast" role="status" aria-live="polite"></div>`;setupInteractions();}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function toast(message){const el=document.querySelector('.toast');el.textContent=message;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);}
async function copy(text){try{if(navigator.clipboard && window.isSecureContext){await navigator.clipboard.writeText(text);}else{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity=0;document.body.append(area);area.select();if(!document.execCommand('copy'))throw new Error('copy');area.remove();}toast('Copiado al portapapeles');}catch{toast('No se pudo copiar. Selecciona el texto y cópialo manualmente.');}}
function setupInteractions(){
 const dialog=document.querySelector('dialog');let opener;
 document.querySelectorAll('[data-open-guide]').forEach(b=>b.addEventListener('click',()=>{opener=b;dialog.showModal();}));
 document.querySelector('[data-close-guide]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>copy(b.dataset.copy==='source'?source:'manim -pql primera_escena.py PrimeraEscena')));
 document.querySelector('[data-download]').addEventListener('click',()=>download('primera_escena.py',source,'text/x-python'));
 document.querySelectorAll('[data-color]').forEach(b=>b.addEventListener('click',()=>copy(b.dataset.color)));
 document.querySelector('[data-tokens]').addEventListener('click',()=>{const t=themes[theme];download(`manim-${theme}-tokens.css`,`/* Manim · ${t.name} — ${t.tag} */\n:root {\n  --bg: ${t.bg};\n  --accent: ${t.accent};\n  --surface: ${t.surface};\n  --text: ${t.text};\n  --sage: #8BBDA3;\n  --coral: #DF866B;\n  --neon-mint: #95EBD0;\n  --neon-lilac: #BDAAFF;\n  --glass-radius: 12px;\n  --glass-edge-lilac: #CBBAFF;\n  --glass-edge-mint: #A6F6D5;\n  --glass-edge-coral: #F5AE96;\n  --radius: ${t.radius.replace(' ','')};\n  --font-body: "Segoe UI", sans-serif;\n  --font-heading: "Segoe UI", sans-serif;\n  --font-code: "SFMono-Regular", Consolas, monospace;\n  --text-sm: 12px;\n  --text-base: 15px;\n  --text-lg: 18px;\n  --heading-sm: 26px;\n  --heading-lg: 48px;\n}\n`,'text/css');});
 const menu=document.querySelector('.menu-button');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);document.querySelector('.sidebar').classList.toggle('mobile-open',open);});
 const lessonLinks=[...document.querySelectorAll('.lesson-link')];
 const selectLesson=hash=>{const target=lessonLinks.some(a=>a.hash===hash)?hash:'#introduccion';lessonLinks.forEach(a=>{const active=a.hash===target;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});};
 selectLesson(location.hash);
 window.addEventListener('hashchange',()=>selectLesson(location.hash));
 lessonLinks.forEach(a=>a.addEventListener('click',()=>{selectLesson(a.hash);document.querySelector('.sidebar').classList.remove('mobile-open');menu.setAttribute('aria-expanded','false');}));
 const complete=document.querySelector('[data-complete]');let completed=false;try{completed=localStorage.getItem('manim-first-lesson')==='true';}catch{}
 const setComplete=()=>{complete.classList.toggle('completed',completed);complete.setAttribute('aria-pressed',String(completed));complete.querySelector('span').textContent=completed?'Lección completada':'Marcar como completada';};setComplete();complete.addEventListener('click',()=>{completed=!completed;try{localStorage.setItem('manim-first-lesson',String(completed));}catch{}setComplete();toast(completed?'¡Una idea más en movimiento!':'Lección marcada como pendiente');});
 const shape=document.querySelector('.morph-shape'), range=document.querySelector('#timeline'), play=document.querySelector('[data-play]');let progress=0,playing=false,startTime=0,raf;
 function draw(){const elapsed=progress*4.5;const creation=Math.min(1,elapsed);const x=Math.max(0,Math.min(1,(elapsed-1.5)/2));const eased=x*x*(3-2*x);shape.style.opacity=Math.max(.3,creation);shape.style.transform=`scale(${.85+.15*creation})`;shape.style.borderRadius=`${50*(1-eased)}%`;shape.style.borderColor=`rgb(${139-6*eased},${175-39*eased},${155+35*eased})`;shape.style.background=`rgba(${139-6*eased},${175-39*eased},${155+35*eased},.25)`;range.value=progress*1000;range.style.setProperty('--progress',`${progress*100}%`);document.querySelector('#time-label').textContent=`${elapsed.toFixed(1)} / 4.5 s`;document.querySelector('#stage-operation').textContent=elapsed<1?'Create(circulo)':elapsed<1.5?'wait(0.5)':elapsed<3.5?'Transform(circulo, cuadrado)':'wait()';}
 function pause(){playing=false;cancelAnimationFrame(raf);play.innerHTML=icon('play',17);play.setAttribute('aria-label','Reproducir animación');}
 function tick(now){progress=Math.min(1,(now-startTime)/4500);draw();if(progress<1)raf=requestAnimationFrame(tick);else pause();}
 play.addEventListener('click',()=>{if(playing){pause();return;}if(progress>=1)progress=0;playing=true;startTime=performance.now()-progress*4500;play.innerHTML='<span aria-hidden="true">Ⅱ</span>';play.setAttribute('aria-label','Pausar animación');raf=requestAnimationFrame(tick);});
 range.addEventListener('input',()=>{pause();progress=range.value/1000;draw();});document.querySelector('[data-reset]').addEventListener('click',()=>{pause();progress=0;draw();});draw();
}
lesson();
